export class ModalBaseCtrl{constructor({mS:mS,commonSvc:commonSvc,tS:tS}){this.mS=mS,this.commonSvc=commonSvc,this.tS=tS}isValidForm(){this.data.idPuntoEmision&&0!==!this.data.idPuntoEmision?!this.data.fechaEmision||this.data.fechaEmision instanceof Date&&!isNaN(this.data.fechaEmision)?this.tS.toastr("warning","Ingrese la fecha de Emisión"):!this.data.fechaVencimiento||this.data.fechaVencimiento instanceof Date&&!isNaN(this.data.fechaEmision)?this.tS.toastr("warning","Ingrese la fecha de vencimiento"):Date.parse(this.data.fechaEmision)<=Date.parse(this.data.fechaVencimiento)&&this.tS.toastr("warning","Fecha de Vencimiento no puede ser menor a  Fecha de Emisión"):this.tS.toastr("warning","Seleccione el Punto de Emisión")}}export class ModalNuevoCtrl extends ModalBaseCtrl{static $inject=["$scope","$uibModalInstance","mainService","commonService","toastService","formulario","params"];constructor($scope,$uibModalInstance,mS,commonSvc,tS,form,params){super({mS:mS,commonSvc:commonSvc,tS:tS}),this.$scope=$scope,this.$uibModalInstance=$uibModalInstance,this.form=form,this.params=params,this.data={},this.dataSearch={typeList:1},this.establecimientos=[],this.puntosEmision=[],this.decimal={},this.tipoIvas=[],this.tiemposCredito=[]}$onInit(){try{this.mS.getData("get","CompraNoHabitual/Get/"+JSON.stringify(this.dataSearch),null,!0).then(response=>{console.log(response)})}catch(error){console.log(error)}}save(){try{if(!this.isValidForm())return;showLoader(),this.mS.getData("post","CompraNoHabitual/Post",this.data).then(response=>{if("0"===response.code)return hideLoader(),void this.form.sweetAlert("warning",response.message);"1"===response.code&&(hideLoader(),this.form.sweetAlert("success",response.message),this.$uibModalInstance.close(response))})}catch(error){hideLoader(),console.log(error)}}closeModal(){this.$uibModalInstance.close()}}export class ModalEditarCtrl extends ModalBaseCtrl{static $inject=["$scope","$uibModalInstance","mainService","toastService","params"];constructor($scope,$uibModalInstance,mS,tS,params){super({mS:mS,commonSvc:commonSvc,tS:tS}),this.$scope=$scope,this.$uibModalInstance=$uibModalInstance,this.params=params,this.data={}}$onInit(){console.log(this)}closeModal(){this.$uibModalInstance.close()}}